function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function capture(){if(!engine||!currentPlacement||$('scene').getAttribute('aria-busy')==='true'){toast('Your merchandise is still loading.');return}await flushArtwork();$('capture').disabled=true;$('capture').textContent='Creating your mockup…';try{const blob=await engine.capture({width:+$('exportSize').value,ratio:+$('exportRatio').value,transparent:$('exportTransparent').checked});if(!blob)throw Error('Capture failed');if(captureURL)URL.revokeObjectURL(captureURL);captureURL=URL.createObjectURL(blob);modal('Your vision, captured.',`<img class="capture-preview" id="capturedImage" alt="Your custom merchandise mockup"><div class="capture-actions"><button id="downloadCapture" class="primary">Download PNG</button><button id="shareCapture" class="secondary">Share image</button></div><p class="panel-help" id="shareHelp">Review the image before sharing. If image sharing is unavailable in this browser, download the PNG and send it in your favourite app.</p>`);$('capturedImage').src=captureURL;$('downloadCapture').onclick=()=>downloadBlob(blob,'pressroom-'+product.id+'-mockup.png');const f=new File([blob],'pressroom-'+product.id+'.png',{type:'image/png'});if(!navigator.canShare?.({files:[f]})){$('shareCapture').disabled=true;$('shareCapture').textContent='Download to share'}else $('shareCapture').onclick=async()=>{try{await navigator.share({files:[f],title:'My Pressroom design'})}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable. Download the PNG instead.')}}}catch(e){toast('Could not create the image. Try a smaller export.');console.error(e)}finally{$('capture').disabled=false;$('capture').innerHTML='<img src="assets/icons/camera.svg" alt="">Preview my mockup'}}
$('capture').onclick=capture;save=()=>{gotoStep('share');capture()};
$('saveDesign').onclick=async()=>{if(!currentPlacement||$('scene').getAttribute('aria-busy')==='true'){toast('Your merchandise is still loading.');return}await flushArtwork();snapshotSurface();const name=projectName($('projectName').value);$('projectName').value=name;updateProjectTitle();const payload={schema:'pressroom-design-v1',name,product:product.id,color:color[1],surfaces:artByProduct[product.id],scene:sceneValues(),camera:engine.getState().camera,export:{ratio:$('exportRatio').value,width:$('exportSize').value,transparent:$('exportTransparent').checked}};downloadBlob(new Blob([JSON.stringify(payload)],{type:'application/json'}),projectFilename(name));toast('Project download started')};
$('loadDesign').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>30*1024*1024)throw Error('File too large');const data=JSON.parse(await f.text());if(data.schema!=='pressroom-design-v1'||!products.some(p=>p.id===data.product)||!/^#[0-9a-f]{6}$/i.test(data.color))throw Error('Invalid design');for(const s of Object.values(data.surfaces||{})){if(!['art','text'].includes(s.mode)||typeof s.text!=='string'||s.text.length>1000||!/^#[0-9a-f]{6}$/i.test(s.ink)||s.image&&!/^data:image\/(png|jpeg);base64,/.test(s.image))throw Error('Invalid artwork');if(!Object.values(s.placement||{}).every(v=>typeof v==='number'&&Number.isFinite(v)&&Number.isFinite(v))||s.placement.w<=0||s.placement.h<=0)throw Error('Invalid placement')}
 snapshotSurface();$('projectName').value=projectName(data.name);updateProjectTitle();product=products.find(p=>p.id===data.product);color=productPalette().find(c=>c[1]===data.color)||['Custom',data.color];artByProduct[product.id]=data.surfaces||{};currentModel=null;update();await rebuild();const ids={light:'lightPreset',intensity:'lightIntensity',azimuth:'lightAzimuth',elevation:'lightElevation',exposure:'exposure',background:'backgroundColor',backgroundMode:'backgroundMode'};for(const [key,id] of Object.entries(ids))if(data.scene?.[key]!==undefined)$(id).value=data.scene[key];$('groundShadow').checked=data.scene?.shadow??true;updateScene();if(data.export){$('exportRatio').value=String(data.export.ratio);$('exportSize').value=String(data.export.width);$('exportTransparent').checked=!!data.export.transparent}if(Array.isArray(data.camera?.position)&&data.camera.position.length===3&&data.camera.position.every(Number.isFinite)){const [x,y,z]=data.camera.position,r=Math.hypot(x,y,z);engine.restoreCamera(data.camera.position,data.camera.target)}gotoStep('place');toast('Project opened')}catch(e){toast('This file is not a supported Pressroom design.')}finally{e.target.value=''}};
rebuild=async()=>{if(!engine)return;if(currentModel===product.id){engine.setColor(color[1]);return}currentModel=product.id;try{await engine.setProduct(product.id,color[1])}catch{currentModel=null;toast('The model could not load. Choose another product or reload.')}};
rotate=a=>engine?.view(a===Math.PI?'back':'front');zoom=d=>engine?.zoom(d);
async function initialize(){engine=await createStudio($('scene'),{onCamera:({azimuth,elevation})=>{$('cameraReadout').textContent=azimuth+'° / '+elevation+'°';$('cameraAzimuth').value=azimuth;$('cameraElevation').value=elevation;$('cameraAzimuthValue').textContent=azimuth+'°';$('cameraElevationValue').textContent=elevation+'°'},onModel:async info=>{spec=info.spec;$('freeTransform').checked=false;$('movePrintArea').checked=false;$('printSide').options[0].textContent=spec.surfaceName||'Front';$('printSide').options[1].disabled=product.supportsBack===false;$('printSide').options[1].hidden=product.supportsBack===false;for(const [key,id] of Object.entries(numeric)){if(key==='w'||key==='h')$(id).min=.1;else $(id).removeAttribute('min');$(id).removeAttribute('max')}$('printAreaInfo').textContent='Print guide: '+spec.maxW+' × '+spec.maxH+' mm. Check final placement with your printer before production.';currentPlacement=info.placement;await restoreSurface('front');await flushArtwork();if(product.supportsBack!==false&&artByProduct[product.id]?.back){await restoreSurface('back');await flushArtwork();await restoreSurface('front');await flushArtwork()}engine.setGuides(step==='place'&&$('printGuides').checked)},onPrintAnchor:anchor=>{updateAnchorStatus(anchor);syncPrintAreaSize(engine.getPrintAreaSize());snapshotSurface()},onTransform:({anchor,placement:p,interactive})=>{const old=currentPlacement;currentPlacement=p;if(artMode==='text'&&old&&Math.abs(p.w-old.w)>.01){textStyle.size=Math.max(8,textStyle.size*p.w/old.w);}if(!interactive){syncTextControls();placementInputs();updateAnchorStatus(anchor);redraw();validatePlacement();snapshotSurface()}},onError:message=>{$('placementStatus').textContent=message}});mapEditor=createSurfaceEditor($('printMap'),{read:()=>({spec,placement:currentPlacement,artCanvas:canvas,hasArtwork:hasArt,side:activeSurface,product,mapping:engine?.getMapping()}),onChange:p=>{if(p.w&&artMode==='text'){textStyle.size=Math.max(8,textStyle.size*p.w/currentPlacement.w);syncTextControls()}place(p);redraw()},onFile:file,onFocus:()=>engine.focusDesign()});$('scene').ondragover=e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()};$('scene').ondrop=e=>{e.preventDefault();file(e.dataTransfer.files[0])};document.dispatchEvent(new CustomEvent('studio-loading',{detail:'Preparing the first model and materials…'}));await rebuild();if(!currentPlacement)throw new Error('Initial model unavailable');gotoStep('design');updateScene();await flushArtwork();await document.fonts.ready;await Promise.all([...document.querySelectorAll('#products img')].filter(img=>img.complete).map(img=>img.decode().catch(()=>{})));await new Promise(requestAnimationFrame);$('loading')?.remove();updateProjectTitle();historyReady=true;commitHistory();document.dispatchEvent(new Event('studio-ready'))}

function sanitiseTextStyle(value){const s={...TEXT_DEFAULTS,...value};s.font=['Arial','Georgia','Courier New','Verdana'].includes(s.font)?s.font:'Arial';s.size=Math.max(8,Number(s.size)||32);s.align=['left','center','right','justify'].includes(s.align)?s.align:'center';s.lineHeight=Math.max(1,Math.min(2,Number(s.lineHeight)||1.25));return s}
function syncTextControls(){$('textFont').value=textStyle.font;$('textSize').value=textStyle.size;$('textLineHeight').value=textStyle.lineHeight;for(const key of ['bold','italic','underline']){const b=$('text'+key[0].toUpperCase()+key.slice(1));b.classList.toggle('selected',!!textStyle[key]);b.setAttribute('aria-pressed',!!textStyle[key])}document.querySelectorAll('[data-align]').forEach(b=>{b.classList.toggle('selected',b.dataset.align===textStyle.align);b.setAttribute('aria-pressed',b.dataset.align===textStyle.align)});$('textHex').value=$('ink').value}
for(const key of ['bold','italic','underline'])$('text'+key[0].toUpperCase()+key.slice(1)).onclick=()=>{textStyle[key]=!textStyle[key];syncTextControls();redraw()};
document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{textStyle.align=b.dataset.align;syncTextControls();redraw()});
$('textFont').onchange=()=>{textStyle.font=$('textFont').value;redraw()};$('textSize').oninput=()=>{textStyle.size=Math.max(8,+$('textSize').value||32);redraw()};$('textLineHeight').onchange=()=>{textStyle.lineHeight=+$('textLineHeight').value;redraw()};$('ink').oninput=()=>{$('textHex').value=$('ink').value;redraw()};$('textHex').oninput=()=>{if(/^#[0-9a-f]{6}$/i.test($('textHex').value)){$('ink').value=$('textHex').value;redraw()}};$('textHex').onblur=()=>{$('textHex').value=$('ink').value};
let resizeOrigin=null;$('visualSize').onpointerdown=()=>{resizeOrigin={...currentPlacement}};$('visualSize').oninput=()=>{if(!currentPlacement)return;resizeOrigin??={...currentPlacement};const factor=+$('visualSize').value/100;const w=Math.max(.1,resizeOrigin.w*factor),h=Math.max(.1,resizeOrigin.h*factor);if(artMode==='text'){textStyle.size=Math.max(8,textStyle.size*w/currentPlacement.w);syncTextControls()}place({w,h});redraw()};$('visualSize').onpointerup=()=>{resizeOrigin=null;$('visualSize').value=100};$('visualRotation').oninput=()=>place({angle:+$('visualRotation').value});$('zeroRotation').onclick=()=>place({angle:0});syncTextControls();
$('growArtwork').onclick=()=>{place({w:currentPlacement.w*1.25,h:currentPlacement.h*1.25});redraw()};$('shrinkArtwork').onclick=()=>{place({w:Math.max(.1,currentPlacement.w*.8),h:Math.max(.1,currentPlacement.h*.8)});redraw()};update();initialize().catch(e=>{document.dispatchEvent(new Event('studio-error'));console.error(e)});



function updateAnchorStatus(anchor){const pose=engine?.getProjectorState();if(pose)for(const key of ['x','y','z','rx','ry','rz']){const input=$('decal-'+key);if(document.activeElement!==input)input.value=Math.round(pose[key]*10)/10}const pick=engine?.getPickInfo();if(pick?.count){$('surfaceLayer').innerHTML=Array.from({length:pick.count},(_,i)=>'<option value="'+i+'">'+(i===0?'Visible surface':'Surface '+(i+1)+' · behind overlap')+'</option>').join('');$('surfaceLayer').value=String(pick.index);$('surfacePickStatus').textContent='Surface '+(pick.index+1)+' of '+pick.count+' at the picked point.'}else{$('surfaceLayer').innerHTML='<option value="0">Visible surface · pick a point first</option>';$('surfacePickStatus').textContent='Click the model, then select a deeper surface if parts overlap.'}$('projectorDepth').disabled=engine?.getMapping()==='wrap';$('projectorOffset').disabled=engine?.getMapping()==='wrap';$('projectorDepth').value=anchor?.depthMm||20;$('projectorOffset').value=anchor?.offsetMm||0;$('printAnchorStatus').textContent=anchor?'Print area moved on the model. Saved with this surface.':'Print area at its default position.';}
$('movePrintArea').onchange=()=>{$('freeTransform').checked=false;engine?.setFreeTransform(false);engine?.setMoveArea($('movePrintArea').checked);engine?.setGuides(true);$('printGuides').checked=true};
$('resetPrintArea').onclick=()=>{$('freeTransform').checked=false;$('movePrintArea').checked=false;engine?.setFreeTransform(false);engine?.setMoveArea(false);engine?.setPrintAnchor(null);syncPrintAreaSize(engine.getPrintAreaSize());updateAnchorStatus(null);snapshotSurface()};

function syncPrintAreaSize(size){spec={...product.print,...engine?.getSurfaceSpec(),maxW:size.w,maxH:size.h};$('printAreaWidth').value=Math.round(size.w*10)/10;$('printAreaHeight').value=Math.round(size.h*10)/10;$('printAreaWidth').max=spec.shape==='wrap'?product.print.maxW:5000;$('printAreaHeight').max=spec.shape==='wrap'?105:5000;$('printAreaHeight').disabled=product.print.shape==='circle';$('printAreaInfo').textContent='Print guide: '+Math.round(size.w)+' × '+Math.round(size.h)+' mm. The model clips artwork where there is no surface. Check final dimensions with your printer.';mapEditor?.render()}
for(const id of ['printAreaWidth','printAreaHeight'])$(id).oninput=()=>{if(!engine||!$(id).value)return;const w=+$('printAreaWidth').value,h=+$('printAreaHeight').value;if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0)return;syncPrintAreaSize(engine.setPrintAreaSize({w,h}));snapshotSurface();validatePlacement()};
$('resetPrintAreaSize').onclick=()=>{syncPrintAreaSize(engine.setPrintAreaSize(null));snapshotSurface();validatePlacement()};

$('freeTransform').onchange=()=>{$('movePrintArea').checked=false;engine?.setMoveArea(false);engine?.setFreeTransform($('freeTransform').checked);engine?.setGuides(true);$('printGuides').checked=true};
$('pickFreeSurface').onclick=()=>{$('freeTransform').checked=false;engine?.setFreeTransform(false);$('movePrintArea').checked=true;engine?.setMoveArea(true,true);engine?.setGuides(true);$('printGuides').checked=true;toast('Click the model to pick a print surface. Orbit first to reach hidden sides.')};
document.querySelectorAll('[data-transform-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-transform-mode]').forEach(x=>x.classList.toggle('selected',x===b));if(!$('freeTransform').checked){$('freeTransform').checked=true;$('freeTransform').onchange()}engine?.setTransformMode(b.dataset.transformMode)});
$('transformSpace').onchange=()=>engine?.setTransformSpace($('transformSpace').value);
$('transformSnap').onchange=()=>engine?.setTransformSnap($('transformSnap').checked);
$('surfaceLayer').onchange=()=>engine?.setPickLayer($('surfaceLayer').value);
for(const id of ['projectorDepth','projectorOffset'])$(id).oninput=()=>{const v=Number($(id).value);if($(id).value!==''&&Number.isFinite(v))engine?.setProjectorOptions({[id==='projectorDepth'?'depthMm':'offsetMm']:v})};

for(const key of ['x','y','z','rx','ry','rz'])$('decal-'+key).oninput=()=>{const input=$('decal-'+key),value=Number(input.value);if(input.value!==''&&Number.isFinite(value))engine?.setProjectorPose({[key]:value})};

document.addEventListener('viewport-navigation',e=>{if(!engine)return;$('freeTransform').checked=false;$('movePrintArea').checked=false;engine.setFreeTransform(false);engine.setMoveArea(false);engine.setNavigation(e.detail)});

document.addEventListener('wheel',e=>{if(e.target.matches('input[type=number]')&&document.activeElement===e.target)e.target.blur()},{passive:true,capture:true});


function copyBanks(banks){return Object.fromEntries(Object.entries(banks).map(([id,surfaces])=>[id,{...surfaces}]))}
function captureHistoryState(){
 snapshotSurface(false);
 return {name:projectName($('projectName').value),product:product.id,color:[...color],colours:Object.fromEntries(Object.entries(productColors).map(([id,c])=>[id,[...c]])),savedColours:[...savedColours],surfaces:copyBanks(artByProduct),side:activeSurface,scene:sceneValues(),quantity:qty,size:$('size').value,export:{ratio:$('exportRatio').value,width:$('exportSize').value,transparent:$('exportTransparent').checked}};
}
function historyStatus(){for(const [id,enabled] of [['undoEdit',history.canUndo],['redoEdit',history.canRedo]])if($(id))$(id).disabled=historyApplying||$('scene').getAttribute('aria-busy')==='true'||!enabled;}
function commitHistory(){clearTimeout(historyTimer);historyTimer=0;if(!historyReady||historyApplying||restoring||$('scene').getAttribute('aria-busy')==='true')return;history.push(captureHistoryState());historyStatus()}
function scheduleHistory(){if(!historyReady||historyApplying||historyGesture)return;clearTimeout(historyTimer);historyTimer=setTimeout(commitHistory,300)}
async function applyHistoryState(state){
 const focused=document.activeElement;if(focused?.matches('input,textarea,select'))focused.blur();
 historyApplying=true;historyStatus();artRevision++;cancelAnimationFrame(renderFrame);renderFrame=0;
 try{
  $('projectName').value=projectName(state.name);updateProjectTitle();artByProduct=copyBanks(state.surfaces);savedColours=[...state.savedColours];for(const key of Object.keys(productColors))delete productColors[key];for(const [id,c]of Object.entries(state.colours))productColors[id]=[...c];
  const changed=product.id!==state.product;product=products.find(p=>p.id===state.product);color=[...state.color];qty=state.quantity;$('size').value=state.size;update();
  if(changed){currentModel=null;await rebuild()}else{engine.setColor(color[1]);engine.resetSurfaces();await restoreSurface('front');await flushArtwork();if(artByProduct[product.id]?.back){await restoreSurface('back');await flushArtwork()}}
  await restoreSurface(state.side);await flushArtwork();
  const ids={light:'lightPreset',intensity:'lightIntensity',azimuth:'lightAzimuth',elevation:'lightElevation',exposure:'exposure',background:'backgroundColor',backgroundMode:'backgroundMode'};for(const [key,id]of Object.entries(ids))$(id).value=state.scene[key];$('groundShadow').checked=state.scene.shadow;updateScene();
  $('exportRatio').value=state.export.ratio;$('exportSize').value=state.export.width;$('exportTransparent').checked=state.export.transparent;
  $('freeTransform').checked=false;$('movePrintArea').checked=false;engine.setFreeTransform(false);engine.setMoveArea(false);persistColours();
 }finally{historyApplying=false;historyStatus();if(focused?.isConnected&&focused.checkVisibility())focused.focus({preventScroll:true});document.dispatchEvent(new Event('history-restored'))}
}
async function historyAction(action){if(historyApplying){if(queuedHistoryActions.length<50)queuedHistoryActions.push(action);return}if(!historyReady||$('scene').getAttribute('aria-busy')==='true')return;commitHistory();const state=action==='undo'?history.undo():history.redo();if(state)try{await applyHistoryState(state)}catch(error){toast('Could not restore this edit.');console.error(error)}const next=queuedHistoryActions.shift();if(next)await historyAction(next)}
document.addEventListener('click',e=>{const button=e.target.closest('#undoEdit,#redoEdit');if(button){historyAction(button.id==='undoEdit'?'undo':'redo');return}if(e.target.closest('.editor-screen,.collection-screen'))scheduleHistory()});
document.addEventListener('input',e=>{if(!e.target.matches('#assetSearch'))scheduleHistory()});
document.addEventListener('change',scheduleHistory);
document.addEventListener('pointerdown',e=>{if(e.button===0&&e.target.closest('.editor-screen,.collection-screen')&&!e.target.closest('#undoEdit,#redoEdit')){commitHistory();historyGesture=true}},true);
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,()=>{if(historyGesture){historyGesture=false;scheduleHistory()}});
window.addEventListener('blur',()=>{historyGesture=false;scheduleHistory()});
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey||e.isComposing||$('modal').open||document.body.dataset.screen!=='studio'||e.target.matches('#assetSearch'))return;const key=e.key.toLowerCase();if(key==='z'||key==='y'&&!e.metaKey){e.preventDefault();historyGesture=false;historyAction(key==='y'||e.shiftKey?'redo':'undo')}});
document.addEventListener('change',e=>{if(e.target.id==='surfaceMapping'){engine?.setMapping(e.target.value);snapshotSurface();validatePlacement();$('projectorDepth').disabled=e.target.value==='wrap';$('projectorOffset').disabled=e.target.value==='wrap';mapEditor?.render()}});

new MutationObserver(()=>{historyStatus();if($('scene').getAttribute('aria-busy')==='false')scheduleHistory()}).observe($('scene'),{attributes:true,attributeFilter:['aria-busy']});

function updateProjectTitle(){const input=$('projectName');document.title=projectName(input.value)+' — Pressroom';input.style.setProperty('--project-title-width',Math.max(16,input.value.length+2)+'ch')}
document.addEventListener('input',e=>{if(e.target.id==='projectName')updateProjectTitle()});
document.addEventListener('focusout',e=>{if(e.target.id==='projectName'){e.target.value=projectName(e.target.value);updateProjectTitle()}});
document.addEventListener('keydown',e=>{if(e.target.id==='projectName'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();e.target.blur();return}if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.key.toLowerCase()==='s'&&!e.isComposing&&document.body.dataset.startup==='ready'){e.preventDefault();if(document.activeElement===$('projectName'))$('projectName').blur();$('saveDesign').click()}});
document.addEventListener('keydown',event=>{
 if(document.body.dataset.startup!=='ready'||document.body.dataset.screen!=='studio'||$('modal').open||event.isComposing)return;
 if((event.ctrlKey||event.metaKey)&&!event.altKey&&event.key.toLowerCase()==='o'){event.preventDefault();$('loadDesign').click();return}
 if(event.target.closest('input,textarea,select,[contenteditable],dialog'))return;
 if(!event.ctrlKey&&!event.metaKey&&!event.altKey&&['Delete','Backspace'].includes(event.key)&&hasArt&&$('scene').getAttribute('aria-busy')!=='true'){event.preventDefault();commitHistory();if(artMode==='text')$('designText').value='';$('clearArt').click()}
});

document.addEventListener('reset-artwork-size',()=>{
 if(!currentPlacement||!spec)return;
 if(artMode==='text'){textStyle.size=TEXT_DEFAULTS.size;syncTextControls()}
 $('scale').value=100;$('scaleValue').textContent='100%';$('visualSize').value=100;resizeOrigin=null;
 place({w:spec.w,h:spec.h});redraw();
});
